import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { AuthService } from '../services/auth.service';

@Component({
  selector: 'app-authentication',
  templateUrl: './authentication.component.html',
  styleUrls: ['./authentication.component.css']
})
export class AuthenticationComponent {
  loginForm: FormGroup;
  submitted = false;
  error = '';

  constructor(
    private formBuilder: FormBuilder,
    private authService: AuthService
  ) {
    this.loginForm = this.formBuilder.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', Validators.required]
    });
  }

  get form() { return this.loginForm.controls; }

  onSubmit() {
    this.submitted = true;
    if (this.loginForm.invalid) {
      return;
    }

    const email = this.form.email.value;
    const password = this.form.password.value;

    this.authService.login(email, password).subscribe(
      (response) => {
        // Handle successful login
      },
      (error) => {
        this.error = 'Invalid email or password';
      }
    );
  }
}
```
This component includes a login form with email and password fields, as well as validation and error handling. It uses Angular Reactive Forms to handle form input and validation.

The `AuthService` is a custom service that handles the authentication logic, such as making API calls to the backend and storing tokens in local storage.

You can then use this component in your HTML template, and style it with CSS frameworks like Bootstrap or Material Design. For example:
```javascript
<div class="container">
  <div class="row justify-content-center">
    <div class="col-md-6">
      <div class="card">
        <div class="card-header">Login</div>
        <div class="card-body">
          <form [formGroup]="loginForm" (ngSubmit)="onSubmit()">
            <div class="form-group">
              <label>Email</label>
              <input type="email" class="form-control" formControlName="email">
              <div *ngIf="form.email.invalid && (form.email.dirty || form.email.touched)" class="invalid-feedback">
                <div *ngIf="form.email.errors.required">Email is required</div>
                <div *ngIf="form.email.errors.email">Invalid email format</div>
              </div>
            </div>
            <div class="form-group">
              <label>Password</label>
              <input type="password" class="form-control" formControlName="password">
              <div *ngIf="form.password.invalid && (form.password.dirty || form.password.touched)" class="invalid-feedback">
                <div *ngIf="form.password.errors.required">Password is required</div>
              </div>
            </div>
            <div class="form-group">
              <button type="submit" class="btn btn-primary" [disabled]="submitted">Login</button>
            </div>
            <div *ngIf="error" class="alert alert-danger">{{ error }}</div>
          </form>
        </div>
      </div>
    </div>
  </div>
</div>
